import{_ as n,o as r,c as s,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const o=JSON.parse('{"title":"Gespeicherte Grundschuldaten einer Gruppe löschen","description":"","frontmatter":{"title":"Gespeicherte Grundschuldaten einer Gruppe löschen","source_pageid":803,"source_revision":2491},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse/grundschuldaten-loeschen-gruppenprozesse-allgemein.md","filePath":"schild3/suchen-gruppenprozesse/grundschuldaten-loeschen-gruppenprozesse-allgemein.md"}'),l={name:"schild3/suchen-gruppenprozesse/grundschuldaten-loeschen-gruppenprozesse-allgemein.md"};function p(i,e,u,c,h,d){return r(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="gespeicherte-grundschuldaten-einer-gruppe-loschen" tabindex="-1">Gespeicherte Grundschuldaten einer Gruppe löschen <a class="header-anchor" href="#gespeicherte-grundschuldaten-einer-gruppe-loschen" aria-label="Permalink to &quot;Gespeicherte Grundschuldaten einer Gruppe löschen&quot;">​</a></h1><p>Entfernen Sie die unter Schulbesuch gespeicherten Grundschuldaten der ausgewählten Schülergruppe, wenn diese nicht mehr benötigt werden.</p><p>Dieser Gruppenprozess ermöglicht das komfortable Löschen der Grundschuldaten der ausgewählten Schülermenge.</p><p>Dabei werden die unter dem Karteireiter <em>Schüler ➜ Schulbesuch ➜ Grundschuldaten eingeben</em> eingegebenen Daten gelöscht.</p><p>Dies sollte durchgeführt werden, wenn die Schülerinnen und Schüler die Erprobungsstufe beendet haben und diese Daten nicht mehr benötigt werden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Grundschuldaten_l%C3%B6schen_(Gruppenprozesse_Allgemein)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 2491.</p>',7)])])}const g=n(l,[["render",p]]);export{o as __pageData,g as default};
